export const defaultSettings=()=>({bannerText:'',bannerEnabled:false,audioEnabled:true,volume:25,loop:true,pauseOnExternal:true,defaultTrack:'background',tracks:[{id:'background',title:'Nhạc nền',url:'assets/audio/background.mp3'}]});
export function directAudioURL(raw){try{const value=String(raw??'').trim();if(/^assets\/audio\/(?:[A-Za-z0-9_-]+\/)*[A-Za-z0-9_-]+\.(?:mp3|m4a|ogg|wav|aac|flac)$/.test(value)&&value.length<=2048)return value;const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password||String(raw).length>2048)return '';if(/(^|\.)(youtube\.com|youtu\.be|spotify\.com|soundcloud\.com|music\.apple\.com)$/.test(u.hostname))return '';return u.href;}catch{return '';}}
export function validateSettings(input){const d={...defaultSettings(),...input};if(typeof d.bannerText!=='string'||d.bannerText.length>500)throw new Error('Thông báo tối đa 500 ký tự.');for(const k of ['bannerEnabled','audioEnabled','loop','pauseOnExternal'])if(typeof d[k]!=='boolean')throw new Error('Cấu hình không hợp lệ.');d.volume=Number(d.volume);if(!Number.isInteger(d.volume)||d.volume<0||d.volume>100)throw new Error('Âm lượng phải từ 0 đến 100.');if(!Array.isArray(d.tracks)||d.tracks.length>8)throw new Error('Tối đa 8 bản nhạc nền.');const ids=new Set();d.tracks=d.tracks.map(t=>{if(!t||typeof t.id!=='string'||!t.id||t.id.length>80||ids.has(t.id))throw new Error('ID bản nhạc không hợp lệ.');ids.add(t.id);if(typeof t.title!=='string'||!t.title.trim()||t.title.length>180)throw new Error('Nhập tên bản nhạc, tối đa 180 ký tự.');const url=directAudioURL(t.url);if(!url)throw new Error('Nhập đường dẫn assets/audio/ten-bai.mp3 hoặc URL âm thanh HTTPS trực tiếp.');return {id:t.id,title:t.title.trim(),url};});if(d.defaultTrack&&!ids.has(d.defaultTrack))throw new Error('Chọn bản nhạc mặc định trong danh sách.');if(d.audioEnabled&&(!d.tracks.length||!d.defaultTrack))throw new Error('Thêm và chọn nhạc mặc định trước khi bật trình phát.');if(d.bannerEnabled&&!d.bannerText.trim())throw new Error('Nhập thông báo trước khi bật banner.');return Object.fromEntries(Object.keys(defaultSettings()).map(k=>[k,d[k]]));}

// Background music starts enabled; old disabled/empty presets use the local track.
export function playbackSettings(input = {}) {
 const fallback = defaultSettings();
 const tracks = Array.isArray(input.tracks) && input.tracks.length ? input.tracks : fallback.tracks;
 const defaultTrack = tracks.some(t => t.id === input.defaultTrack) ? input.defaultTrack : tracks[0].id;
 return validateSettings({...fallback, ...input, tracks, defaultTrack, audioEnabled: true});
}
